type ApiResponseError = { error?: string; detail?: string; message?: string }
async function readJsonResponse<T>(response: Response): Promise<T> {
  const body = await response.text()
  if (!body.trim()) {
    throw new Error(response.ok ? '服务器返回了空响应，请确认后端已启动。' : `请求失败（HTTP ${response.status}），服务器没有返回 JSON。`)
  }
  try {
    return JSON.parse(body) as T
  } catch {
    const preview = body.replace(/\s+/g, ' ').slice(0, 120)
    throw new Error(`服务器返回的不是有效 JSON（HTTP ${response.status}）：${preview}`)
  }
}
const chordPitches = (root: number) => [root, root + 4, root + 7]
