  const triggerGesture = (e: React.PointerEvent<HTMLCanvasElement>, force = false) => { const el = canvas.current; if (!el || (!gesture.current.active && !force)) return; const r = el.getBoundingClientRect(); const x = Math.max(0, Math.min(r.width, e.clientX - r.left)); const y = Math.max(0, Math.min(r.height, e.clientY - r.top)); const nx = x / r.width; const ny = y / r.height; const now = performance.now(); const row = Math.max(0, Math.min(gestureScale.length - 1, Math.floor((1 - ny) * gestureScale.length))); const column = Math.max(0, Math.min(5, Math.floor(nx * 6))); const cell = `${row}:${column}`; const elapsed = Math.max(16, now - gesture.current.at); const distance = Math.hypot(x - gesture.current.x, y - gesture.current.y); cursor.current = { x, y, active: true }; if (!force && (cell === gesture.current.cell || now - gesture.current.at < 58)) return; const velocity = Math.max(.35, Math.min(1, .38 + distance / elapsed * .55)); const duration = .22 + nx * .28; const pitch = gestureScale[row]; const chord = chordPitches(pitch); gesture.current = { active: true, x, y, at: now, cell }; playChord(chord, velocity, duration, nx); const color = nx > .66 ? '#fb9ab0' : nx > .33 ? '#b9a7ff' : '#7dd3fc'; for (let i = 0; i < 3; i++) particles.current.push({ x: x + (Math.random() - .5) * 16, y: y + (Math.random() - .5) * 16, r: 2 + Math.random() * 5, life: 1, color }); if (recording) { const start = Math.min(9.8, Math.max(0, (now - recordingStarted.current) / 1000)); const chordNotes: Note[] = chord.map((chordPitch, index) => ({ id: `${now}-${row}-${column}-${index}`, pitch: chordPitch, start, duration, velocity: Math.round(velocity * 127 * (index === 0 ? 1 : .72)) })); setProject(p => ({ ...p, tracks: p.tracks.map(t => t.id === 'melody' ? { ...t, notes: [...(t.notes ?? []), ...chordNotes].slice(-96) } : t) })) } }
